129	// GetStoredIdentityProvider returns a database-backed provider without deployment shadowing.
130	func (s *Store) GetStoredIdentityProvider(ctx context.Context, find *FindIdentityProvider) (*storepb.IdentityProvider, error) {
131		list, err := s.listStoredIdentityProviders(ctx, find)
132		if err != nil {
133			return nil, err
134		}
135		if len(list) == 0 {
136			return nil, nil
137		}
138		if len(list) > 1 {
139			return nil, errors.New("found multiple stored identity providers")
140		}
141		return list[0], nil
142	}
