152	func (s *Store) UpdateIdentityProvider(ctx context.Context, update *UpdateIdentityProviderV1) (*storepb.IdentityProvider, error) {
153		updateRaw := &UpdateIdentityProvider{
154			ID: update.ID,
155		}
156		if update.Name != nil {
157			updateRaw.Name = update.Name
158		}
159		if update.IdentifierFilter != nil {
160			updateRaw.IdentifierFilter = update.IdentifierFilter
161		}
162		if update.Config != nil {
