189	func convertIdentityProviderFromRaw(raw *IdentityProvider) (*storepb.IdentityProvider, error) {
190		identityProvider := &storepb.IdentityProvider{
191			Id:               raw.ID,
192			Uid:              raw.UID,
193			Name:             raw.Name,
194			Type:             raw.Type,
195			IdentifierFilter: raw.IdentifierFilter,
196		}
197		config, err := convertIdentityProviderConfigFromRaw(identityProvider.Type, raw.Config)
198		if err != nil {
199			return nil, err
200		}
201		identityProvider.Config = config
202		return identityProvider, nil
